/**
 * Where the human base comes from: MakeHuman's bundled assets (base mesh,
 * shape targets, rig, eyes), released under CC0 1.0 (the program code is
 * AGPL and is not used). Pinned to one commit; every file's size and
 * SHA-256 are in `makehuman-pins.ts`, generated by `scripts/pin-makehuman.ts`.
 */
export const MAKEHUMAN_SOURCE = {
	repo: "makehumancommunity/makehuman",
	commit: "a8bc2d54ff0ac92e78ff71431b1023eda42bf482",
	license: "CC0-1.0",
	/** Raw file URL for a path under `makehuman/data/`. */
	url(path: string): string {
		return `https://raw.githubusercontent.com/${this.repo}/${this.commit}/makehuman/data/${path}`;
	},
} as const;
